'use strict';
const FRANCHISE_UI10={storesView,openDialog,bind,gameContext6,digestDestination6,digestActionLabel6};
const FN_FINDINGS10={coffee:'Chybí použitelná káva',quality:'Kvalita pod smluvním cílem',equipment:'Opotřebené vybavení',staffing:'Nedostatečná kapacita směn'};
function franchiseListUI10(){show(`<div id="franchiseDialog10"><span class="eyelabel">PROVOZOVATELÉ A LICENCE</span><h2>Tvoje franšízy</h2><p>Jmenný provozovatel řídí směny, ceny a místní marketing. Kontroly a nápravu schvaluješ ty. Káva se čerpá ze skutečného společného skladu.</p>${state.franchises10.licenses.length?state.franchises10.licenses.slice().reverse().map(x=>`<article class="gr-item8"><strong>${esc(loc(x.location).city)} · ${esc(loc(x.location).name)}</strong><p>${esc(x.operator.name)} · ${FN_STATUS10[x.status]}${x.deadline?' · termín T'+x.deadline:''}</p><button class="soft" data-fn-report10="${x.id}">Otevřít smlouvu a výsledky</button></article>`).join(''):'<p class="empty">Zatím nemáš podrobnou smlouvu. Novou franšízu založíš z volné adresy při pověsti 65.</p>'}${state.stores.filter(s=>s.franchise&&!franchiseAt10(s.id)).map(s=>`<article class="gr-item8"><strong>Dosavadní franšíza · ${esc(loc(s.id).name)}</strong><p>Pokračuje původní řízení. Podrobný provozovatel a jeho smlouva stojí 6 000 Kč.</p><button class="soft" data-fn-enroll10="${s.id}">Vybrat provozovatele</button></article>`).join('')}</div>`);experimentTop9();franchiseBindDialog10();}
function franchiseBindDialog10(){const root=el('modalContent');root.querySelectorAll('[data-fn-report10]').forEach(b=>b.onclick=()=>franchiseReportUI10(b.dataset.fnReport10));root.querySelectorAll('[data-fn-enroll10]').forEach(b=>b.onclick=()=>franchiseOpeningUI10(b.dataset.fnEnroll10,true));}
function franchiseOpeningUI10(location,existing=false){const s=state.stores.find(s=>s.id===location),list=franchiseCandidates10(location);show(`<div id="franchiseDialog10"><span class="eyelabel">${esc(loc(location).city)} · FRANŠÍZA</span><h2>${esc(loc(location).name)}</h2><p>${existing?'Podrobná smlouva nahradí souhrnné řízení dosavadní franšízy. Historický výsledek a zaplacené zásoby zůstanou.':'Centrála financuje 25 % základního otevření a přípravu. Provozovatel řídí kavárnu; centrála získává 11 % hrubých tržeb a hradí fyzickou kávu. Mzdy, nájem, menu a místní marketing nese provozovatel.'}</p><div class="fields">${field('Provozovatel',`<select id="fnOperator10">${list.map(p=>option(p.source,p.label+' · provoz '+round(p.person.strength.operations)+', tým '+round(p.person.strength.people)+', káva '+round(p.person.strength.product))).join('')}</select>`)}${field('Cíl řízení',`<select id="fnGoal10"><option value="quality">Kvalita</option><option value="service">Obsluha a kapacita</option><option value="profit">Výsledek provozovatele</option></select>`)}${field('Smluvní kvalita / 100',input('fnQuality10',70,60,90))}${field('Limit místního marketingu / týden',input('fnAds10',3000,0,10000,500))}${field('Rezerva centrály / týdny',input('fnReserve10',3,1,8))}${!existing?field('Značka',`<select id="fnBrand10">${brandOptions(state.brands[0].id)}</select>`)+field('Kávová receptura',`<select id="fnBlend10">${blendOptions(state.blends[0].id)}</select>`)+field('Zásobování',`<select id="fnProvider10"><option value="local">${esc(COFFEE_SUPPLIERS6.local.name)} · sjednání ${money(COFFEE_SUPPLIERS6.local.fee)}</option><option value="specialty">${esc(COFFEE_SUPPLIERS6.specialty.name)} · sjednání ${money(COFFEE_SUPPLIERS6.specialty.fee)}</option><option value="own">Vlastní zásoby a doprava</option></select>`)+field('Cílová zásoba hotové kávy / kg',input('fnTarget10',25,5,100))+field('Limit nákupů kávy / týden',input('fnCoffeeBudget10',20000,0,100000,500)):''}</div><p class="sub">Smlouva a výběr provozovatele: ${existing?'6 000':'12 000'} Kč. Provozní směny mají souhrnné počty pracovníků; mzdy se účtují podle skutečného rozpisu. Příprava nové franšízy trvá pět týdnů a zkouška čeká na fyzickou kávu.</p><button class="primary" id="fnOpeningQuote10">Prověřit celou cenu a rezervu</button></div>`);experimentTop9();el('fnOpeningQuote10').onclick=()=>{try{const source=el('fnOperator10').value,policy={goal:el('fnGoal10').value,quality:Number(el('fnQuality10').value),adBudget:Number(el('fnAds10').value)},reserve=Number(el('fnReserve10').value),data=existing?null:{brand:el('fnBrand10').value,blend:el('fnBlend10').value,operator:source,policy,reserve,provider:el('fnProvider10').value,target:Number(el('fnTarget10').value),budget:Number(el('fnCoffeeBudget10').value)},q=existing?franchiseEnrollQuote10(location,source,policy,reserve):franchiseOpeningQuote10(location,data),total=existing?q.fee:q.total;show(`<div id="franchiseDialog10"><h2>Schválit provozovatele</h2>${rows([['Provozovatel',esc(q.operator.name)],['Jeho odměna při provozu / týden',money(q.operator.salary)],['Celá platba centrály nyní',money(total)],['Hotovost po platbě',money(q.cash-total)],['Chráněná rezerva',money(q.protectedCash)]])}<p>Výběr kávy není zásoba. Dodávky se platí zvlášť; kávu stejné směsi sdílí kavárny ve městě.</p><button class="primary" id="fnOpeningApprove10" ${!q.safe?'disabled':''}>Schválit za ${money(total)}</button>${!q.safe?'<p class="bad">Platba by porušila rezervu centrály.</p>':''}</div>`);experimentTop9();el('fnOpeningApprove10').onclick=()=>acquisitionConfirmUI9('Podepsat franšízovou smlouvu?',esc(q.operator.name)+' · '+money(total)+' nyní. Budoucí skutečný provoz a káva se platí dál.',()=>existing?enrollFranchise10(location,source,policy,reserve,q):startFranchise10(location,data,q),'Podepsat a zaplatit',()=>franchiseReportUI10(franchiseAt10(location).id));}catch(e){toast(e.message);}};}
function franchiseFinancialUI10(x){const f=x.financials.at(-1);if(!f)return '<p class="empty">První finanční a provozní výsledek přijde po skutečném týdnu této smlouvy.</p>';return `<h3>Skutečný týden ${f.week}</h3>${rows([['Hrubé tržby hostů',money(f.gross)],['Provozovatel před daní a odpisy',money(f.partnerProfit)],['Licenční příjem centrály',money(f.royalty)],['Spotřebovaná káva centrály',money(f.coffee)],['Příspěvek franšízy centrále',money(f.companyProfit)],['Obslouženo / poptávka',number(f.served)+' / '+number(f.demand)],['Nedostatky kávy / kapacity',number(f.stockLost)+' / '+number(f.capacityLost)],['Kvalita / stav vybavení',(f.quality===null?'Bez prodaného vzorku':number(f.quality))+' / '+number(f.condition)+' %']])}<details><summary>Náklady provozovatele</summary>${rows([['Mzdy směn',money(f.wages)],['Odměna provozovatele',money(f.manager)],['Odvody zaměstnavatele',money(f.payroll)],['Nájem',money(f.rent)],['Suroviny menu',money(f.ingredients)],['Provoz a energie',money(f.overhead+f.utilities)],['Místní marketing',money(f.marketing)],['Provoz vybavení',money(f.equipment)],['Platby kartou',money(f.cardFees)],['DPH z tržeb provozovatele',money(f.vat)]])}<p class="sub">Výsledek není hotovostní zůstatek partnera. Centrála účtuje licenční příjem a kávu jen jednou; její audit a školení jsou samostatné náklady.</p></details>`;}
function franchiseReportUI10(id){const x=franchiseLicense10(id),p=franchiseOperator10(x),audits=state.franchises10.audits.filter(a=>a.license===id),plans=state.franchises10.plans.filter(a=>a.license===id),live=state.stores.some(s=>s.id===x.location&&s.franchise);show(`<div id="franchiseDialog10"><span class="eyelabel">${FN_STATUS10[x.status]}</span><h2>${esc(loc(x.location).name)} · ${esc(p.name)}</h2>${rows([['Provoz / tým / káva',[p.strength.operations,p.strength.people,p.strength.product].map(n=>number(n)).join(' / ')+' ze 100'],['Cíl řízení',{quality:'Kvalita',service:'Obsluha a kapacita',profit:'Výsledek provozovatele'}[x.policy.goal]],['Limit místního marketingu',money(x.policy.adBudget)+' / týden'],['Smluvní kvalita',x.policy.quality+' / 100'],['Termín nápravy',x.deadline?'T'+x.deadline:'—']])}${x.status!=='ended'?'<button class="soft" id="fnPolicy10">Upravit cíle provozovatele</button>':''}${x.status==='preparing'?'<p>Příprava pokračuje. Zkušební provoz potřebuje skutečně doručenou kávu.</p><button class="soft" id="fnOpeningReport10">Otevřít přípravu</button>':''}${live?`<p>${esc(cafeCoffeeStatus6(x.location,state.stores.find(s=>s.id===x.location).blend).text)}</p><div class="actions"><button class="soft" id="fnSupply10">Nastavit dodávky kávy</button>${!audits.some(a=>a.status==='pending')?'<button class="primary" id="fnAudit10">Objednat kontrolu za 5 000 Kč</button>':''}${['warning','suspended','probation'].includes(x.status)&&audits.some(a=>a.status==='completed'&&a.findings.length)&&!plans.some(p=>['scheduled','monitoring'].includes(p.status))?'<button class="primary" id="fnPlan10">Připravit placenou nápravu</button>':''}${x.status==='suspended'?'<button class="soft" id="fnEnd10">Prověřit ukončení licence</button>':''}</div>`:''}${x.status==='suspended'?'<p class="warning">Prodej pod značkou je pozastaven. Nájem a tým dál stojí peníze provozovatele. Placená náprava povolí zkušební provoz se 70 % poptávky; plná licence se vrátí až po ověřeném výsledku.</p>':''}${franchiseFinancialUI10(x)}${franchiseHistoryUI10(x)}${franchiseDecisionsUI10(x)}<h3>Kontroly kvality</h3>${audits.length?audits.slice().reverse().map(a=>`<article class="gr-item8"><strong>${a.status==='pending'?'Probíhá do T'+a.due:a.status==='completed'?'Kontrola skutečného T'+a.snapshot.week:'Kontrola nedostupného provozu'}</strong><p>Zaplaceno ${money(a.fee)} · standard kvality ${a.standard.quality}/100</p>${a.status==='completed'?`<p>${a.findings.length?a.findings.map(k=>FN_FINDINGS10[k]).join(' · '):'Zjištěné podmínky splněny.'}</p>`:''}</article>`).join(''):'<p>Zatím nebyla zaplacena kontrola.</p>'}<h3>Nápravné plány</h3>${plans.length?plans.slice().reverse().map(plan=>`<article class="gr-item8"><strong>${{scheduled:'Zaplacená práce čeká',monitoring:'Probíhá ověření',passed:'Náprava splněna',failed:'Náprava nesplněna',unavailable:'Provoz již není dostupný'}[plan.status]} · termín T${plan.deadline}</strong><p>Celkem ${money(plan.cost)} · servis a školení nejdřív od T${plan.workDue}</p>${plan.rows.length?`<details><summary>${plan.rows.length} skutečných týdenních výsledků</summary>${plan.rows.map(f=>`<p>T${f.week} · ${f.served} hostů · kvalita ${f.quality===null?'bez vzorku':f.quality} · stav ${number(f.condition)} % · chybějící káva ${f.stockLost}</p>`).join('')}</details>`:''}</article>`).join(''):'<p>Zatím žádná placená náprava.</p>'}<button class="soft" id="fnList10">Všechny franšízy</button></div>`);experimentTop9();el('fnList10').onclick=franchiseListUI10;if(el('fnPolicy10'))el('fnPolicy10').onclick=()=>franchisePolicyUI10(id);if(el('fnOpeningReport10'))el('fnOpeningReport10').onclick=()=>openingProjectDialog6(x.opening);if(el('fnSupply10'))el('fnSupply10').onclick=()=>gameSupplierDialog6(x.location);if(el('fnAudit10'))el('fnAudit10').onclick=()=>{try{const q=franchiseAuditQuote10(id,3);if(!q.safe)return toast('Kontrola by porušila tři týdny rezervy centrály.');acquisitionConfirmUI9('Zaplatit kontrolu?',money(q.fee)+' nyní. Výsledek přijde po skutečném týdnu, v T'+q.due+'.',()=>startFranchiseAudit10(id,3,q),'Zaplatit kontrolu',()=>franchiseReportUI10(id));}catch(e){toast(e.message);}};if(el('fnPlan10'))el('fnPlan10').onclick=()=>franchisePlanUI10(id);if(el('fnEnd10'))el('fnEnd10').onclick=()=>{try{const q=franchiseTerminateQuote10(id);acquisitionConfirmUI9('Ukončit pozastavenou licenci?','Adresa přestane být součástí sítě. Vrácení peněz 0 Kč; vybavení partnera se nepřevede zdarma. Historie a zaplacená káva zůstanou.',()=>terminateFranchise10(id,q),'Ukončit smlouvu',()=>franchiseReportUI10(id));}catch(e){toast(e.message);}};}
function franchisePlanUI10(id){const x=franchiseLicense10(id),s=state.stores.find(s=>s.id===x.location);show(`<div id="franchiseDialog10"><h2>Náprava · ${esc(loc(x.location).name)}</h2><p>Práci zaplatíš nyní. Servis a školení proběhnou po příštím týdnu; závěrečné ověření použije skutečný provoz a původní standard kontroly.</p><label class="gr-check8"><input id="fnRepair10" type="checkbox" checked> Servis opotřebeného vybavení za skutečnou cenu</label><label class="gr-check8"><input id="fnTrain10" type="checkbox" checked> Školení kávy provozovatele · 12 000 Kč, nejvýše +8</label><label class="gr-check8"><input id="fnStaff10" type="checkbox"> Zaplatit návrh nových směn · 6 000 Kč</label><div class="fields">${s.daily.shifts.map((n,i)=>field(['Ranní směna','Polední směna','Večerní směna'][i],input('fnShift10-'+i,n,0,7))).join('')}${field('Termín ověření / týdny',input('fnWeeks10',3,2,6))}${field('Chráněná rezerva centrály / týdny',input('fnPlanReserve10',3,1,8))}</div><p class="sub">Koordinace a závěrečné ověření stojí 5 000 Kč. Dodávky kávy nastav samostatně; nápravný plán nevytváří zásoby a neplatí budoucí směnové mzdy.</p><button class="primary" id="fnPlanQuote10">Prověřit celou nápravu</button></div>`);experimentTop9();el('fnPlanQuote10').onclick=()=>{try{const d={repair:el('fnRepair10').checked,train:el('fnTrain10').checked,shifts:el('fnStaff10').checked?[0,1,2].map(i=>Number(el('fnShift10-'+i).value)):null,weeks:Number(el('fnWeeks10').value),reserve:Number(el('fnPlanReserve10').value)},q=franchisePlanQuote10(id,d);show(`<div id="franchiseDialog10"><h2>Schválit nápravu</h2>${rows([['Koordinace a ověření',money(q.fee)],['Skutečný servis',money(q.equipment.reduce((n,e)=>n+e.cost,0))],['Školení provozovatele',money(q.train?.cost||0)],['Návrh směn',money(q.staffing)],['Celkem nyní',money(q.total)],['Hotovost po platbě',money(q.cash-q.total)],['Chráněná rezerva',money(q.protectedCash)]])}<p>Práce od T${state.week+1}, závěrečný skutečný provoz T${state.week+d.weeks}. Po nesplnění se licence pozastaví. Kvalita musí dosáhnout ${q.standard.quality}/100; nedostatky kávy nejvýše 10 %, kapacity 20 %, stav vybavení alespoň 75 %.</p><button class="primary" id="fnPlanApprove10" ${!q.safe?'disabled':''}>Zaplatit ${money(q.total)}</button></div>`);experimentTop9();el('fnPlanApprove10').onclick=()=>acquisitionConfirmUI9('Zaplatit nápravný plán?',money(q.total)+' nyní. Výsledek závisí na skutečném provozu a dostupné kávě.',()=>startFranchisePlan10(id,d,q),'Zaplatit nápravu',()=>franchiseReportUI10(id));}catch(e){toast(e.message);}};}
storesView=function(){return `<section class="card"><span class="eyelabel">FRANŠÍZOVÁ SÍŤ</span><h2>Provozovatelé, kvalita a licence</h2><p>${state.franchises10.licenses.filter(x=>x.status!=='ended').length} podrobných smluv · ${state.franchises10.licenses.filter(x=>x.status==='suspended').length} pozastavených licencí. Příjem centrály a výsledek provozovatele najdeš odděleně.</p><button class="soft" data-fn-list10>Otevřít přehled franšíz</button></section>`+FRANCHISE_UI10.storesView();};
openDialog=function(id,franchise=false){return franchise?franchiseOpeningUI10(id):FRANCHISE_UI10.openDialog(id,franchise);};
bind=function(){FRANCHISE_UI10.bind();document.querySelectorAll('[data-fn-list10]').forEach(b=>b.onclick=franchiseListUI10);};
gameContext6=function(){FRANCHISE_UI10.gameContext6();const x=gameSelection6?.kind==='address'&&franchiseAt10(gameSelection6.id),box=el('gameContext6');if(x&&box&&!el('fnContext10')){box.insertAdjacentHTML('beforeend','<button class="game-primary6" id="fnContext10">Provozovatel a franšízová licence</button>');el('fnContext10').onclick=()=>franchiseReportUI10(x.id);}};

digestDestination6=function(item){if(item.key.startsWith('franchise-contract-')&&state.franchises10.licenses.some(x=>x.id===item.target)){closeDigest6();franchiseReportUI10(item.target);return;}return FRANCHISE_UI10.digestDestination6(item);};
digestActionLabel6=function(item){return item.key.startsWith('franchise-contract-')?'Otevřít franšízovou smlouvu':FRANCHISE_UI10.digestActionLabel6(item);};
const FRANCHISE_CONTEXT10=gameContext6;
gameContext6=function(){FRANCHISE_CONTEXT10();if(gameSelection6?.kind!=='address'||gameEditing6||state.reputation<65)return;const id=gameSelection6.id,actions=el('gameContext6')?.querySelector('.game-panel-actions6');if(actions&&grFree8(id)&&!el('fnContextStart10')){actions.insertAdjacentHTML('beforeend','<button id="fnContextStart10">Založit franšízu s provozovatelem</button>');el('fnContextStart10').onclick=()=>franchiseOpeningUI10(id);}};

function franchisePolicyUI10(id){const x=franchiseLicense10(id);show(`<div id="franchiseDialog10"><h2>Cíle · ${esc(x.operator.name)}</h2><p>Nové cíle platí pro další řízení. Zaplacené kontroly a nápravné plány uchovají původní standard.</p><div class="fields">${field('Cíl řízení',`<select id="fnPolicyGoal10">${Object.entries({quality:'Kvalita',service:'Obsluha a kapacita',profit:'Výsledek provozovatele'}).map(([k,n])=>option(k,n,x.policy.goal)).join('')}</select>`)}${field('Smluvní kvalita / 100',input('fnPolicyQuality10',x.policy.quality,60,90))}${field('Limit místního marketingu / týden',input('fnPolicyAds10',x.policy.adBudget,0,10000,500))}</div><p>Změna cíle je zdarma. Budoucí marketing a směny hradí provozovatel podle skutečného rozpisu.</p><button class="primary" id="fnPolicyQuote10">Prověřit změnu cílů</button></div>`);experimentTop9();el('fnPolicyQuote10').onclick=()=>{try{const d={goal:el('fnPolicyGoal10').value,quality:Number(el('fnPolicyQuality10').value),adBudget:Number(el('fnPolicyAds10').value)},q=franchisePolicyQuote10(id,d);acquisitionConfirmUI9('Změnit cíle provozovatele?','Kvalita '+q.policy.quality+'/100, marketing nejvýše '+money(q.policy.adBudget)+'/týden. Staré audity zůstanou beze změny.',()=>setFranchisePolicy10(id,d,q),'Uložit nové cíle',()=>franchiseReportUI10(id));}catch(e){toast(e.message);}};}
const FRANCHISE_CREW_CONTEXT10=gameContext6;
gameContext6=function(){FRANCHISE_CREW_CONTEXT10();const x=gameSelection6?.kind==='address'&&franchiseAt10(gameSelection6.id);if(x&&el('gameCafeCrew6')){el('gameCafeCrew6').textContent='Provozovatel a směny';el('gameCafeCrew6').onclick=()=>franchiseReportUI10(x.id);}};

function franchiseHistoryUI10(x){return !x.financials.length?'':`<details><summary>Finanční historie · ${x.financials.length} skutečných týdnů</summary><div class="table-scroll" tabindex="0" aria-label="Finanční historie franšízy"><table><thead><tr><th>Týden</th><th>Hrubé tržby</th><th>Provozovatel</th><th>Centrála po kávě</th><th>Hosté</th><th>Kvalita</th></tr></thead><tbody>${x.financials.slice().reverse().map(f=>`<tr><td>${f.week}</td><td>${money(f.gross)}</td><td>${money(f.partnerProfit)}</td><td>${money(f.companyProfit)}</td><td>${number(f.served)}</td><td>${f.quality===null?'Bez vzorku':number(f.quality)}</td></tr>`).join('')}</tbody></table></div></details>`;}

function franchiseDecisionsUI10(x){const s=state.stores.find(s=>s.id===x.location&&s.manager?.pid===x.operator.pid),f=x.financials.at(-1);return !s||s.daily.last?.week!==f?.week||!s.last?.decisions?.length?'':`<details><summary>Rozhodnutí provozovatele · T${f.week}</summary>${s.last.decisions.map(t=>`<p>${esc(t)}</p>`).join('')}</details>`;}
